old_string:
// Check if any purchased variant belongs to the entry's product
const productMatchRows = await sql<{ id: string }[]>`
  SELECT id FROM waitlist_entries
  WHERE product_external_id = ${entry.product_external_id}::bigint
  AND variant_external_id = ANY(
    ARRAY[${variantIdStrings.join(",")}]::bigint[]
  )
  LIMIT 1
`;

new_string:
// Check if any purchased variant belongs to the entry's product
// Use IN clause with individually parameterized values for safety
const variantBigints = variantIdStrings.map((s) => `${s}::bigint`).join(", ");
const productMatchRows = await sql<{ id: string }[]>`
  SELECT id FROM waitlist_entries
  WHERE product_external_id = ${entry.product_external_id}::bigint
  AND variant_external_id IN (${sql.unsafe(variantBigints)})
  LIMIT 1
`;
